package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class WorkRateRelationsTest {
 @Test public void normalCreationAndDistinctWorkSelectionHaveRelationshipFrames(){Generator g=new Generator(new Random(1820));for(String id:List.of("compoundProportion","combinedWorkTime"))for(int i=0;i<500;i++){Question q=g.next(id,List.of(),false);assertEquals(id.equals("compoundProportion")?8:6,q.studyGuide.frames.size());String signature=q.signature();List<String> expected=q.studyGuide.frames.stream().map(f->f.expected).toList();Arrays.fill(q.answers,"999999");q.choiceInputs=new Rational[]{Rational.of(999999)};HelpPlan p=HelpPlan.forQuestion(q);assertEquals(signature,q.signature());assertFalse(p.canTransfer());assertEquals(expected.size(),p.size());for(int k=0;k<p.size();k++){assertTrue(p.step(k).accepts(expected.get(k)));assertFalse(p.step(k).accepts(Expression.number(expected.get(k)).add(Rational.ONE).toString()));assertFalse(p.step(k).before.replace("1 ÷ ","").matches("(?s).*\\d.*"));}}}
 @Test public void savedFractionalTimesAndNewDraftRestoreExactly(){Question q=new Question("combinedWorkTime","같은 일을 A는 혼자 3/2시간, B는 혼자 9/4시간에 끝냅니다.\n각자의 작업 속도는 일정합니다.\n둘이 동시에 시작하면 몇 시간이 걸리나요?","","9/10");HelpPlan p=HelpPlan.forQuestion(q);List<String> values=List.of("1.5","2.25","2/3","4/9","10/9","9/10");for(int k=0;k<6;k++)assertTrue(p.step(k).accepts(values.get(k)));HelpPlan.Draft d=new HelpPlan.Draft();d.questionId=q.id;d.stage=1;d.entries=new ArrayList<>(List.of("2/3",""));p.restore(d,q.id);assertEquals(0,d.stage);assertEquals("",d.entries.get(0));d.entries.set(0,"3/2");d.stage=1;HelpPlan.Draft restored=HelpPlan.forQuestion(q).restore(d.copy(),q.id);assertEquals(1,restored.stage);assertEquals("3/2",restored.entries.get(0));}
 @Test public void savedCompoundFractionsUseOnlyPublicInputs(){Question q=new Question("compoundProportion","각 사람의 작업 속도는 일정하고 모두 같습니다.\n2명이 3/2시간에 9개를 만듭니다.\n3명이 9/4시간에 만드는 개수는?","","81/4");HelpPlan p=HelpPlan.forQuestion(q);List<String> values=List.of("2","3/2","9","3","9/4","3/2","3/2","81/4");assertEquals(8,p.size());for(int k=0;k<8;k++)assertTrue(p.step(k).accepts(values.get(k)));}
}
